  ($pp$Point Isabel Regional Shoreline$pp$, $pp$point-isabel$pp$, $pp$park$pp$::public.place_type, $pp$East Bay Regional Park District$pp$, 37.8998, -122.3187, $pp$east_bay_north$pp$::public.region, $pp$Richmond$pp$, $pp$off_leash_ok$pp$::public.dog_status, $pp$Dogs may be off leash here as long as they are under their owner's control, except where posted. The district calls it its most dog-friendly park.$pp$, $pp$Carry a leash (6 ft max) and use it in parking lots and developed areas. Park-specific posted rules apply.$pp$, $pp$https://ebparks.org/dogs$pp$, $pp$verified$pp$::public.verification_status, $pp$2026-11-07$pp$::date, $pp$claude (official page fetch), pending human review$pp$, null, 90, $pp$editorial$pp$, '{}'::text[], $pp$yes$pp$, $pp$none$pp$, null, 60, $pp$2026-11-07T00:00:00.000Z$pp$::timestamptz, $pp$2026-11-07T00:00:00.000Z$pp$::timestamptz),
  ($pp$Tilden Regional Park$pp$, $pp$tilden$pp$, $pp$park$pp$::public.place_type, $pp$East Bay Regional Park District$pp$, 37.9087, -122.2448, $pp$east_bay_central$pp$::public.region, $pp$Berkeley$pp$, $pp$off_leash_zones$pp$::public.dog_status, $pp$District-wide rule: dogs may be off leash in open space and undeveloped areas if they are in view and under voice control, and must return to leash when called. Leash (6 ft max) is required in developed areas, parking lots, picnic areas, grazing areas and for the first 200 ft of a trailhead. Dogs are not allowed at the Tilden Nature Area, the Botanic Garden or the golf course.$pp$, $pp$This rule comes from the district-wide dogs page; this park has no park-specific rule listed there. Posted signs override.$pp$, $pp$https://ebparks.org/dogs$pp$, $pp$verified$pp$::public.verification_status, $pp$2026-11-07$pp$::date, $pp$claude (official page fetch), pending human review$pp$, null, 90, $pp$editorial$pp$, array[$pp$ticks$pp$, $pp$poison_oak$pp$, $pp$cyclists$pp$]::text[], null, null, null, 120, $pp$2026-11-07T00:00:00.000Z$pp$::timestamptz, $pp$2026-11-07T00:00:00.000Z$pp$::timestamptz),
