  ($pp$Pulgas Ridge Open Space Preserve$pp$, $pp$pulgas-ridge$pp$, $pp$trail$pp$::public.place_type, $pp$Midpeninsula Regional Open Space District$pp$, 37.493, -122.285, $pp$south_bay$pp$::public.region, $pp$Redwood City$pp$, $pp$off_leash_zones$pp$::public.dog_status, $pp$All trails are open to dogs on a leash of 6 ft or less. The preserve has a marked off-leash area. Dogs are not allowed in Midpen water areas, including streams and ponds.$pp$, $pp$In the marked off-leash area, keep a leash in your possession and keep your dog under voice control.$pp$, $pp$https://www.openspace.org/what-to-do/activities/dogs$pp$, $pp$verified$pp$::public.verification_status, $pp$2026-11-07$pp$::date, $pp$claude (official page fetch), pending human review$pp$, null, 90, $pp$editorial$pp$, array[$pp$foxtails$pp$, $pp$ticks$pp$]::text[], $pp$none$pp$, null, null, 60, $pp$2026-11-07T00:00:00.000Z$pp$::timestamptz, $pp$2026-11-07T00:00:00.000Z$pp$::timestamptz),
