  ($pp$Lake Sonoma Recreation Area$pp$, $pp$lake-sonoma-recreation-area$pp$, $pp$park$pp$::public.place_type, $pp$U.S. Army Corps of Engineers$pp$, 38.7181, -123.0094, $pp$north_bay$pp$::public.region, $pp$Geyserville$pp$, null, null, null, $pp$https://www.spn.usace.army.mil/Missions/Recreation/Lake-Sonoma/$pp$, $pp$needs_verification$pp$::public.verification_status, null, null, $pp$The Army Corps of Engineers page could not be read by automated access (it returned an error), so the dog rule was not confirmed. Check the Corps page or call the park before you go.$pp$, 90, $pp$editorial$pp$, '{}'::text[], null, null, null, null, $pp$2026-11-15T00:00:00.000Z$pp$::timestamptz, $pp$2026-11-15T00:00:00.000Z$pp$::timestamptz),
  ($pp$Lake Del Valle Regional Recreation Area$pp$, $pp$lake-del-valle$pp$, $pp$park$pp$::public.place_type, $pp$East Bay Regional Park District$pp$, 37.5965, -121.7062, $pp$east_bay_south$pp$::public.region, $pp$Livermore$pp$, $pp$off_leash_zones$pp$::public.dog_status, $pp$District-wide rule: dogs may be off leash in open space and undeveloped areas if they are in view and under voice control, and must return to leash when called. Leash (6 ft max) is required in developed areas, parking lots, picnic areas, grazing areas and for the first 200 ft of a trailhead. Dogs are not allowed at any swimming pool, beach, wetland, marsh or designated nature study area.$pp$, $pp$This rule comes from the district-wide dogs page; this park has no park-specific rule listed there. Posted signs override.$pp$, $pp$https://ebparks.org/dogs$pp$, $pp$verified$pp$::public.verification_status, $pp$2026-11-15$pp$::date, $pp$claude (official page fetch), pending human review$pp$, null, 90, $pp$editorial$pp$, '{}'::text[], null, null, null, null, $pp$2026-11-15T00:00:00.000Z$pp$::timestamptz, $pp$2026-11-15T00:00:00.000Z$pp$::timestamptz),
