from (values
  ($pp$point-isabel$pp$, $pp${"src":"/photos/point-isabel.jpg","alt":"Dirt path and cypress trees near the entrance of Point Isabel Regional Shoreline","credit":"Ndołkah","license":"CC BY-SA 4.0","source_url":"https://commons.wikimedia.org/wiki/File:Pointislabelregionalshoreline2019.jpg","license_url":"https://creativecommons.org/licenses/by-sa/4.0"}$pp$, $pp${"trails":[],"park_wide":["The park page mentions more than 2.5 miles of San Francisco Bay Trail in the vicinity of the park.","Dogs must be on a leash in parking lots and streets."],"sources":[{"label":"East Bay Regional Park District: Point Isabel","url":"https://www.ebparks.org/parks/point-isabel"}],"verified_on":"2026-11-15"}$pp$),
  ($pp$tilden$pp$, $pp${"src":"/photos/tilden.jpg","alt":"Hazy hills and trees seen from Selby Trail in Tilden Regional Park","credit":"Mliu92","license":"CC BY-SA 3.0","source_url":"https://commons.wikimedia.org/wiki/File:Tilden_Regional_Park_5.jpg","license_url":"https://creativecommons.org/licenses/by-sa/3.0"}$pp$, $pp${"trails":[],"park_wide":["The park page says there are 39.41 miles of trails in Tilden Park. That is all trails, not only ones open to dogs.","Dogs must be on a leash on Nimitz Way.","Dogs are not allowed in the swim facility at Lake Anza."],"sources":[{"label":"East Bay Regional Park District: Tilden","url":"https://www.ebparks.org/parks/tilden"}],"verified_on":"2026-11-15"}$pp$),
  ($pp$briones$pp$, $pp${"src":"/photos/briones.jpg","alt":"Green rolling hills along Lafayette Ridge in Briones Regional Park","credit":"Mrbilal1987 (assumed author)","license":"Public domain","source_url":"https://commons.wikimedia.org/wiki/File:Lafayette_Ridge_-_Briones_Regional_Park_-_San_San_Francisco.jpg","license_url":null}$pp$, $pp${"trails":[],"park_wide":["Dogs must be on a leash (6 feet maximum) at all times on Tavan Trail, and on parts of Diablo View, Alhambra Creek and Orchard trails."],"sources":[{"label":"East Bay Regional Park District: Briones","url":"https://www.ebparks.org/parks/briones"}],"verified_on":"2026-11-15"}$pp$),
  ($pp$redwood-regional$pp$, $pp${"src":"/photos/redwood-regional.jpg","alt":"Tall redwood trunks in Redwood Regional Park","credit":"Binksternet","license":"Public domain","source_url":"https://commons.wikimedia.org/wiki/File:RedwoodRegional.jpg","license_url":null}$pp$, $pp${"trails":[],"park_wide":["The park page says there are nearly 40 miles of trails. That is all trails, not only ones open to dogs.","The park page shows a \"Dogs Allowed\" icon but does not say which trails."],"sources":[{"label":"East Bay Regional Park District: Redwood Regional","url":"https://www.ebparks.org/parks/redwood"}],"verified_on":"2026-11-15"}$pp$),
  ($pp$sibley$pp$, $pp${"src":"/photos/sibley.jpg","alt":"Golden hills and an extinct volcano summit at Sibley Volcanic Regional Preserve","credit":"Sarah Stierch","license":"CC0","source_url":"https://commons.wikimedia.org/wiki/File:Sibley_Volcanic_Regional_Preserve_-_Stierch_A.jpg","license_url":"https://creativecommons.org/publicdomain/zero/1.0/deed.en"}$pp$, $pp${"trails":[],"park_wide":["Dogs are permitted at Sibley, but are not allowed on the adjacent Huckleberry trails."],"sources":[{"label":"East Bay Regional Park District: Sibley","url":"https://www.ebparks.org/parks/sibley"}],"verified_on":"2026-11-15"}$pp$),
  ($pp$fort-funston$pp$, $pp${"src":"/photos/fort-funston.jpg","alt":"Overlook at Fort Funston with a hang glider and the coastline","credit":"Viriditas","license":"CC BY-SA 3.0","source_url":"https://commons.wikimedia.org/wiki/File:Funston_overlook_2.jpg","license_url":"https://creativecommons.org/licenses/by-sa/3.0"}$pp$, $pp${"trails":[],"park_wide":["The NPS page says its networked trails are ideal for accessible hiking, horseback riding and dog walking.","The loop trails are paved and wheelchair-accessible; the trails down to the beach are not."],"sources":[{"label":"NPS: Fort Funston","url":"https://www.nps.gov/goga/planyourvisit/fortfunston.htm"}],"verified_on":"2026-11-15"}$pp$),
  ($pp$crissy-field$pp$, $pp${"src":"/photos/crissy-field.jpg","alt":"Crissy Field beach with the Golden Gate Bridge in the distance","credit":"Brocken Inaglory","license":"Public domain","source_url":"https://commons.wikimedia.org/wiki/File:Crissy_Field_beach_and_Golden_Gate_Bridge.jpg","license_url":null}$pp$, null),
  ($pp$ocean-beach$pp$, $pp${"src":"/photos/ocean-beach.jpg","alt":"Cliff House above Ocean Beach at sunset","credit":"Brocken Inaglory","license":"CC BY-SA 3.0","source_url":"https://commons.wikimedia.org/wiki/File:Cliff_House_from_Ocean_Beach.jpg","license_url":"https://creativecommons.org/licenses/by-sa/3.0"}$pp$, null),
  ($pp$baker-beach$pp$, $pp${"src":"/photos/baker-beach.jpg","alt":"Baker Beach at dusk with the Golden Gate Bridge in the distance","credit":"BradleyPelton","license":"CC BY-SA 4.0","source_url":"https://commons.wikimedia.org/wiki/File:BakeBeachAtMidday.jpg","license_url":"https://creativecommons.org/licenses/by-sa/4.0"}$pp$, null),
  ($pp$lands-end$pp$, $pp${"src":"/photos/lands-end.jpg","alt":"Coastal trail at Lands End with the Golden Gate Bridge beyond cypress trees","credit":"Pi.1415926535","license":"CC BY-SA 3.0","source_url":"https://commons.wikimedia.org/wiki/File:Coastal_Trail_and_Golden_Gate_Bridge,_April_2019.JPG","license_url":"https://creativecommons.org/licenses/by-sa/3.0"}$pp$, null),
  ($pp$muir-beach$pp$, $pp${"src":"/photos/muir-beach.jpg","alt":"Muir Beach with people on the sand and houses on the hillside","credit":"Frank Schulenburg","license":"CC0","source_url":"https://commons.wikimedia.org/wiki/File:Muir_Beach_as_seen_from_the_beach,_December_2013.jpg","license_url":"https://creativecommons.org/publicdomain/zero/1.0/deed.en"}$pp$, null),
  ($pp$muir-woods$pp$, $pp${"src":"/photos/muir-woods.jpg","alt":"A dirt path through tall redwoods at Muir Woods","credit":"Matthew Dillon","license":"CC BY 2.0","source_url":"https://commons.wikimedia.org/wiki/File:Muir_Woods_National_Monument_(47879029461).jpg","license_url":"https://creativecommons.org/licenses/by/2.0"}$pp$, null),
