);

insert into public.sunday_picks (place_id, week_start, note, sort_order)
select p.id, v.week_start, v.note, v.sort_order
from (values
  ($pp$point-isabel$pp$, $pp$2026-11-09$pp$::date, $pp$Off-leash fun by the bay. Bring a leash for the parking lot.$pp$, 0),
  ($pp$fort-funston$pp$, $pp$2026-11-09$pp$::date, $pp$Big sandy bluffs and voice-control zones. Check posted signs.$pp$, 1),
  ($pp$lands-end$pp$, $pp$2026-11-09$pp$::date, $pp$Coastal trail walk. Leashed or voice control per the park.$pp$, 2),
  ($pp$pulgas-ridge$pp$, $pp$2026-11-09$pp$::date, $pp$On-leash trails plus a marked off-leash area.$pp$, 3)
) as v (slug, week_start, note, sort_order)
join public.places p on p.slug = v.slug
on conflict (week_start, place_id) do nothing;
